  CONSTRAINT `cancion_ibfk_1` FOREIGN KEY (`ID_Album`) REFERENCES `album` (`ID_Album`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
