DROP TABLE IF EXISTS `reproduccion`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `reproduccion` (
  `ID_Repro` int NOT NULL AUTO_INCREMENT,
  `ID_Usuario` int NOT NULL,
  `ID_Cancion` varchar(50) NOT NULL,
  `dispositivo` enum('mobile','desktop','speaker') NOT NULL,
  `fecha` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `duracion` int NOT NULL DEFAULT '1',
  PRIMARY KEY (`ID_Repro`),
  KEY `ID_Usuario` (`ID_Usuario`),
  KEY `ID_Cancion` (`ID_Cancion`),
  CONSTRAINT `reproduccion_ibfk_1` FOREIGN KEY (`ID_Usuario`) REFERENCES `usuario` (`ID_Usuario`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `reproduccion_ibfk_2` FOREIGN KEY (`ID_Cancion`) REFERENCES `cancion` (`ID_Cancion`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=50001 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

